import { mapArrayElementsKeysToObjectKeys } from '../../../../helpers/utility'
import { EB_ACTIONS } from './actions'

const reducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case EB_ACTIONS.RESET_STATE:
      return { ...state, ...mapArrayElementsKeysToObjectKeys(payload) }
    case EB_ACTIONS.FILE_UPLOADS_LIST:
    case EB_ACTIONS.GCS_UPLOAD:
    case EB_ACTIONS.PROVIDERS_LIST:
    case EB_ACTIONS.LEAD_CONFIG:
    case EB_ACTIONS.MARKETING_LIST:
    case EB_ACTIONS.CLAIM_CONFIG:
    case EB_ACTIONS.UPLOAD_FILE_STANDALONE:
    case EB_ACTIONS.DOWNLOAD_FILE_UPLOADS:
    case EB_ACTIONS.CANCEL_FILE:
    case EB_ACTIONS.FILE_ROWS:
    case EB_ACTIONS.FILE_DETAIL:
    case EB_ACTIONS.EXPORT_EXCEL:
    case EB_ACTIONS.CASE_QUOTATION_REMARKS:
      return { ...state, ...payload }
    default:
      return state
  }
}

export default reducer
