import React from 'react'
import { Button, Icon } from 'antd'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import DeactivateParticipant from '../components/DeactivateParticipant'

export const employeeListColumns = ({ companyId, deactivateParticipantsRequest, history }) => {
  return [
    {
      title: 'Actions',
      render: (rowData) => (
        <PermissionCheckerV2
          requiredPermission='ops.eb_view_participant_detail'
        >
          <Icon
            type='eye'
            twoToneColor='#0180c8'
            theme='twoTone'
            style={{ cursor: 'pointer' }}
            onClick={() => history.push(`/employee-benefits/company-list/${companyId}/employee-list/${rowData.id}`)}
          />
        </PermissionCheckerV2>
      ),
      key: 1
    },
    {
      title: 'Name',
      dataIndex: 'name',
      key: 2
    },
    {
      title: 'Status',
      dataIndex: 'status_display',
      key: 3
    },
    {
      title: 'DOB',
      dataIndex: 'dob',
      key: 4
    },
    {
      title: 'Health Card Status',
      dataIndex: 'health_card_status_display',
      key: 5
    },
    {
      title: 'Dependents Count',
      dataIndex: 'dependents_count',
      key: 6
    },
    {
      title: 'Actions',
      render: rowData => (
        <>
          {
            !['DEACTIVATED'].includes(rowData.status)
              ? (
                <DeactivateParticipant
                  onSubmit={(values) => {
                    deactivateParticipantsRequest({ company_id: companyId, employee_ids: [rowData.id], ...values })
                  }}
                  participantName={rowData.name}
                >
                  <Button
                    type='danger'
                    shape='round'
                    size='small'
                  >
                    Deactivate
                  </Button>
                </DeactivateParticipant>
                )
              : null
          }
        </>
      ),
      key: 7
    }
  ]
}
