import { useServiceRequest, useResetError } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useEmployeeList = () => {
  const [{ employeeListData, employeeListStatus }, dispatch] = useEBContextValue()
  const { resetError } = useResetError()
  const [callApi] = useServiceRequest(dispatch)

  const getEmployeeList = (payload = {}) => {
    resetError(['EMPLOYEE_LIST_ERROR'])
    callApi(actions.getEmployeeList({ query: payload }))
  }

  return { employeeListData, employeeListStatus, getEmployeeList }
}

export const useDeactivateParticipants = () => {
  const [{ deactivateParticipantsData, deactivateParticipantsStatus }, dispatch] = useEBContextValue()
  const { resetError } = useResetError()
  const [callApi] = useServiceRequest(dispatch)

  const deactivateParticipantsRequest = (payload = {}) => {
    resetError(['DEACTIVATE_PARTICIPANTS_ERROR'])
    callApi(actions.deactivateParticipant({ body: payload }))
  }

  return { deactivateParticipantsData, deactivateParticipantsStatus, deactivateParticipantsRequest }
}
