import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {
  EMPLOYEE_LIST_REQUEST: 'EMPLOYEE_LIST_REQUEST',
  EMPLOYEE_LIST: 'EMPLOYEE_LIST',
  DEACTIVATE_PARTICIPANTS_REQUEST: 'DEACTIVATE_PARTICIPANTS_REQUEST',
  DEACTIVATE_PARTICIPANTS: 'DEACTIVATE_PARTICIPANTS',

  getEmployeeList: payload => ({
    type: actions.EMPLOYEE_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getEmployeeList
    }
  }),
  deactivateParticipant: payload => ({
    type: actions.DEACTIVATE_PARTICIPANTS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.deactivateParticipants
    }
  })
}

export default actions
