/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import { Typography, Table, Alert, Spin, Row, Col, Button, Icon, Input } from 'antd'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { RowWithMargin } from '../../../CommonComponents'
import { employeeListColumns } from './utility'
import { useDeactivateParticipants, useEmployeeList } from '../../../state/EmployeeList/hooks/useEmployeeList'
import { ColTextAlignRight } from '../../../CommonComponents/index.style'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
const { Title } = Typography

const EmployeeList = ({ history, match, ...props }) => {
  const { employeeListData, getEmployeeList } = useEmployeeList()
  const [{
    EMPLOYEE_LIST_ERROR,
    deactivateParticipantsStatus,
    DEACTIVATE_PARTICIPANTS_ERROR,
    employeeListStatus
  }] = useErrorContextValue()
  const { deactivateParticipantsData, deactivateParticipantsRequest } = useDeactivateParticipants()
  const [{ EMPLOYEE_LIST_LOADER, DEACTIVATE_PARTICIPANTS_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()
  const [listData, setListData] = useState([])
  const [listMetaData, setListMetaData] = useState({ pageSize: 10, page: 1 })
  const [failedRowIds] = useState([])
  const [successRowIds, setSuccessRowIds] = useState([])
  const [searchText, setSearchText] = useState('')

  const callGetEmployeeList = () => {
    const query = {
      company_id: match.params.companyId,
      offset: (listMetaData.page - 1) * 10,
      limit: listMetaData.pageSize
    }
    getEmployeeList(query)
  }

  const handleTableChange = (params) => {
    const query = {
      company_id: match.params.companyId,
      offset: (params.current - 1) * 10,
      limit: params.pageSize
    }
    if (searchText) {
      query.search_text = searchText
    }
    setListMetaData((listMetaData) => ({ ...listMetaData, page: params.current }))
    getEmployeeList(query)
  }

  const openAddParticipantPage = () => {
    history.push(`/employee-benefits/company-list/${match.params.companyId}/add-participant`)
  }

  useEffect(() => {
    const timeOut = searchText ? 1000 : 0
    const debounceTimer = setTimeout(() => {
      if (searchText) {
        getEmployeeList({
          company_id: match.params.companyId,
          search_text: searchText,
          offset: (listMetaData.page - 1) * 10,
          limit: listMetaData.pageSize
        })
      } else {
        getEmployeeList({
          company_id: match.params.companyId,
          offset: (listMetaData.page - 1) * 10,
          limit: listMetaData.pageSize
        })
      }
    }, timeOut)
    return () => clearTimeout(debounceTimer)
  }, [searchText])

  useEffect(() => {
    if (successRowIds && successRowIds.length) {
      const timer = setTimeout(() => { setSuccessRowIds([]) }, 5000)
      return () => clearTimeout(timer)
    }
  }, [successRowIds])

  useEffect(() => {
    if (!EMPLOYEE_LIST_ERROR && employeeListData && Array.isArray(employeeListData.data)) {
      setListData(employeeListData.data)
      setListMetaData({ ...listMetaData, totalRecords: employeeListData.total_records })
    }
  }, [employeeListData])

  useEffect(() => {
    if (!DEACTIVATE_PARTICIPANTS_ERROR && deactivateParticipantsData && deactivateParticipantsData.data) {
      const { data } = deactivateParticipantsData
      if (Array.isArray(data.employee_success)) {
        setSuccessRowIds(data.employee_success)
        callGetEmployeeList()
      }
    }
  }, [deactivateParticipantsData])

  useEffect(() => {
    // getEmployeeList({ company_id: match.params.companyId })
    return () => {
      resetError(['EMPLOYEE_LIST_ERROR', 'DEACTIVATE_PARTICIPANTS_ERROR', 'employeeListStatus', 'deactivateParticipantsStatus'])
    }
  }, [])

  return (
    <EbEmptyPage
      history={history}
      path={`/employee-benefits/company-list/${match.params.companyId}`}
    >
      {(EMPLOYEE_LIST_ERROR) && <Alert type='error' message={employeeListStatus} banner />}
      {(DEACTIVATE_PARTICIPANTS_ERROR) && <Alert type='error' message={deactivateParticipantsStatus} banner />}
      <Spin spinning={!!DEACTIVATE_PARTICIPANTS_LOADER || !!EMPLOYEE_LIST_LOADER}>
        <RowWithMargin type='flex' justify='space-between'>
          <Col span={6}>
            <Title level={4}>Employee List</Title>
          </Col>
          <Col span={18}>
            <Row type='flex' gutter={16} justify='end'>
              <Col span={10}>
                <Input.Search
                  placeholder='Search by Employee Name'
                  onChange={e => setSearchText(e.target.value)}
                  onSearch={setSearchText}
                  value={searchText}
                  allowClear
                  disabled={!!EMPLOYEE_LIST_LOADER}
                />
              </Col>
              <Col>
                <PermissionCheckerV2
                  requiredPermission='ops.eb_add_participant'
                >
                  <ColTextAlignRight span={4}>
                    <Button type='primary' onClick={openAddParticipantPage}><Icon type='user-add' /> Add Participant</Button>
                  </ColTextAlignRight>
                </PermissionCheckerV2>
              </Col>
            </Row>
          </Col>
        </RowWithMargin>
        <Table
          key={listData}
          columns={employeeListColumns({ companyId: match.params.companyId, deactivateParticipantsRequest, history })}
          dataSource={listData}
          onChange={handleTableChange}
          pagination={{
            pageSize: listMetaData.pageSize,
            total: listMetaData.totalRecords,
            current: listMetaData.page
          }}
          onRow={(rowData) => ({
            style: { backgroundColor: successRowIds.includes(rowData.id) ? 'rgb(24 234 10 / 48%)' : failedRowIds.includes(rowData.id) ? 'rgb(255 31 42 / 54%)' : '' }
          })}
          rowKey={record => record.id}
        />
      </Spin>
    </EbEmptyPage>
  )
}

export default EmployeeList
