import React from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'

class PermissionChecker extends React.Component {
  render () {
    const {
      permissions,
      requiredPermission,
      defaultComponent = null
    } = this.props
    if (permissions.find((permissionName) => permissionName === requiredPermission)) {
      return this.props.children
    }
    return defaultComponent
  }
}

PermissionChecker.propTypes = {
  permissions: PropTypes.array.isRequired,
  requiredPermission: PropTypes.string.isRequired
}

PermissionChecker.defaultProps = {
  permissions: []
}

export default connect(
  state => ({
    permissions: state.Auth.permissions
  }),
  {}
)(PermissionChecker)
