import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { DatePicker, Form, Modal } from 'antd'
import moment from 'moment'
import { useCallback, useEffect, useState } from 'react'
import { DEACTIVATE_PARTICIPANT_FORM_FIELDS } from './constants'

const DeactivateParticipant = ({ form, onSubmit, participantName, statusKey, ...props }) => {
  const { getFieldDecorator, validateFields, resetFields, setFieldsValue } = form
  const [error] = useErrorContextValue()
  const { resetError } = useResetError()
  const [visible, setVisible] = useState(false)
  const handleDeactivate = useCallback(() => {
    validateFields((err, values) => {
      if (!err) {
        const clonedValues = { ...values }
        clonedValues[DEACTIVATE_PARTICIPANT_FORM_FIELDS.EFFECTIVE_RESIGNATION_DATE] = values[DEACTIVATE_PARTICIPANT_FORM_FIELDS.EFFECTIVE_RESIGNATION_DATE]
          .format('YYYY-MM-DD')
        onSubmit(clonedValues)
      }
    })
  }, [onSubmit, validateFields])

  useEffect(() => {
    if (error[statusKey] === 'success') {
      resetError([statusKey])
      setVisible(false)
    }
  }, [resetError, statusKey, error])

  useEffect(() => {
    if (!visible) {
      resetFields()
    } else {
      setFieldsValue({
        [DEACTIVATE_PARTICIPANT_FORM_FIELDS.EFFECTIVE_RESIGNATION_DATE]: moment()
      })
    }
  }, [visible, resetFields, setFieldsValue])

  return (
    <>
      <div
        onClick={() => setVisible(true)}
      >
        {props.children}
      </div>
      <Modal
        visible={visible}
        onOk={handleDeactivate}
        onCancel={() => setVisible(false)}
        title={`Deactivate participant - ${participantName}`}
        okText='Deactivate'
      >
        <Form>
          <Form.Item label='Effective Resignation Date'>
            {
              getFieldDecorator(DEACTIVATE_PARTICIPANT_FORM_FIELDS.EFFECTIVE_RESIGNATION_DATE, {
                rules: [
                  {
                    required: true,
                    message: 'This field is required'
                  }
                ]
              })(
                <DatePicker />
              )
            }
          </Form.Item>
        </Form>
      </Modal>
    </>
  )
}
export default Form.create({ name: 'deactivate-dependent-form' })(DeactivateParticipant)
